const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Kariba geometry (approximate center and area)
  const lakeKariba = ee.Geometry.Polygon([
    [[27.5, -16.5], [29.0, -16.5], [29.0, -17.5], [27.5, -17.5], [27.5, -16.5]]
  ]);

  // 2. Date ranges
  const date2018Start = '2018-12-01';
  const date2018End = '2018-12-31';
  const date2019Start = '2019-12-01';
  const date2019End = '2019-12-31';

  // 3. Load Sentinel-2 data for both periods
  let col2018 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeKariba)
    .filterDate(date2018Start, date2018End)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  let col2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeKariba)
    .filterDate(date2019Start, date2019End)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size2018 = col2018.size().getInfo();
  const size2019 = col2019.size().getInfo();

  console.log(`2018 Images: ${size2018}`);
  console.log(`2019 Images: ${size2019}`);

  // Fallback to Landsat 8 if Sentinel-2 fails
  if (size2018 === 0) {
    col2018 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeKariba)
      .filterDate(date2018Start, date2018End)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
  }

  if (size2019 === 0) {
    col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeKariba)
      .filterDate(date2019Start, date2019End)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
  }

  const finalSize2018 = col2018.size().getInfo();
  const finalSize2019 = col2019.size().getInfo();

  if (finalSize2018 === 0 || finalSize2019 === 0) {
    console.log('No data available for comparison');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 5. Calculate NDWI (water index) for both periods
  function addNDWI(image) {
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    return image.addBands(ndwi);
  }

  const img2018 = col2018.map(maskS2clouds).map(addNDWI).median();
  const img2019 = col2019.map(maskS2clouds).map(addNDWI).median();

  // 6. Calculate water area (NDWI > 0 indicates water)
  const water2018 = img2018.select('NDWI').gt(0);
  const water2019 = img2019.select('NDWI').gt(0);

  const area2018 = water2018.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeKariba,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const area2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeKariba,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Water pixels 2018: ${area2018}`);
  console.log(`Water pixels 2019: ${area2019}`);

  // 7. Validation and final answer
  if (area2018 === null || area2019 === null || area2018 === undefined || area2019 === undefined) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  if (area2018 === 0 && area2019 === 0) {
    console.log('No valid water pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  const percentChange = ((area2019 - area2018) / area2018 * 100).toFixed(2);
  console.log(`Change: ${percentChange}%`);

  if (area2019 > area2018) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
